(1543840, 205028, 24454, '<td valign="top">Wow!  Great capture!!!   And you managed to capture him against a beautiful sky and background.    Great job!</td>', 'Wow!  Great capture!!!   And you managed to capture him against a beautiful sky and background.    Great job!', '2005-07-18 13:15:20.000000', NULL, 1),
