INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1546397, 205379, 29477, '<td valign="top">The colours seem really over exaggerated and you have some hot spots on her paws.  Would definately have toned down the colours and zoom out slightly to include her paws.  Good Luck.</td>', 'The colours seem really over exaggerated and you have some hot spots on her paws.  Would definately have toned down the colours and zoom out slightly to include her paws.  Good Luck.', '2005-07-19 13:46:45.000000', NULL, 1),
