(1546609, 204920, 24454, '<td valign="top">Wow!  Gorgeous. . . STRIKING photo!!!!</td>', 'Wow!  Gorgeous. . . STRIKING photo!!!!', '2005-07-19 14:52:27.000000', NULL, 1),
(1546612, 203903, 38921, '<td valign="top">Excellent, similar to the shot I wanted to take but neither the animals or light would not cooperate.  (9)</td>', 'Excellent, similar to the shot I wanted to take but neither the animals or light would not cooperate.  (9)', '2005-07-19 14:52:42.000000', NULL, 1),
(1546614, 205364, 34659, '<td valign="top">Nice shot grasshopper!  I would like to see him a little more close-up though.  Most of the detail is lost because he''s so small.  However, I do really like the greens and the water droplets too.  (I''m sure these little guys are all over most zoos!)  Nice shot.</td>', 'Nice shot grasshopper!  I would like to see him a little more close-up though.  Most of the detail is lost because he''s so small.  However, I do really like the greens and the water droplets too.  (I''m sure these little guys are all over most zoos!)  Nice shot.', '2005-07-19 14:53:32.000000', NULL, 1),
(1546616, 202828, 24454, '<td valign="top">Awwww. . . . I just love polar bear shots.   My favorite animal in the zoo. . .and our zoo mercifully doesn''t even have them (too hot).   This is great.  It shows such detail in his fur, and he has such a great "polar bear" expression.  I love it!!!</td>', 'Awwww. . . . I just love polar bear shots.   My favorite animal in the zoo. . .and our zoo mercifully doesn''t even have them (too hot).   This is great.  It shows such detail in his fur, and he has such a great "polar bear" expression.  I love it!!!', '2005-07-19 14:53:59.000000', NULL, 1),
