(1548381, 205226, 39144, '<td valign="top">Fit Challenge Criteria: 2/2<br/>Color/Contrast: 1/2<br/>Composition: 2/2<br/>Photo Quality: 2/2<br/>My Subjective Affinity: 2/2<br/> <br/>Really nice work on this photo. Composition is great. The only area of improvement I see is in the color. It seems a bit flat or dull.</td>', 'Fit Challenge Criteria: 2/2Color/Contrast: 1/2Composition: 2/2Photo Quality: 2/2My Subjective Affinity: 2/2 Really nice work on this photo. Composition is great. The only area of improvement I see is in the color. It seems a bit flat or dull.', '2005-07-20 01:18:10.000000', NULL, 1),
(1548392, 205086, 39144, '<td valign="top">Fit Challenge Criteria: 2/2<br/>Contrast/Color: 2/2<br/>Composition: 2/2<br/>Photo Quality: 2/2<br/>My Subjective Affinity: 0/2<br/> <br/>Really nice composition and coloring, but the photo as a whole doesn''t appeal to me.</td>', 'Fit Challenge Criteria: 2/2Contrast/Color: 2/2Composition: 2/2Photo Quality: 2/2My Subjective Affinity: 0/2 Really nice composition and coloring, but the photo as a whole doesn''t appeal to me.', '2005-07-20 01:19:40.000000', NULL, 1),
