(1557463, 204093, 41098, '<td valign="top">So powerful... I really like this picture. If only the sky would have been blue.</td>', 'So powerful... I really like this picture. If only the sky would have been blue.', '2005-07-23 17:15:56.000000', NULL, 1),
(1557464, 205456, 41098, '<td valign="top">So much character.</td>', 'So much character.', '2005-07-23 17:16:07.000000', NULL, 1),
